/*
 * Generates internal/seal/testdata/golden.txt with libsodium, so the seal
 * package is checked against the real library rather than against itself.
 *
 * The nonce handling is copied from upstream Eternal Terminal
 * (src/base/CryptoHandler.cpp at et-v7.0.0): a 24-byte nonce whose last byte
 * is the stream MSB, incremented little-endian from byte 0 before every
 * crypto_secretbox_easy call.
 *
 * Build and run from the repository root (needs libsodium-dev):
 *   cc -O2 -Wall -Wextra -o /tmp/et-golden internal/seal/testdata/gen/golden.c -lsodium
 *   /tmp/et-golden > internal/seal/testdata/golden.txt
 *
 * Go ignores testdata directories, so this file is never compiled by go build.
 */
#include <sodium.h>
#include <stdio.h>
#include <string.h>

static const char *key_text = "0123456789ABCDEFGHIJKLMNOPQRSTUV";

static void increment(unsigned char *nonce) {
    for (size_t a = 0; a < crypto_secretbox_NONCEBYTES; a++) {
        nonce[a]++;
        if (nonce[a]) {
            break;
        }
    }
}

static void hex(const unsigned char *b, size_t n) {
    for (size_t i = 0; i < n; i++) {
        printf("%02x", b[i]);
    }
}

static int wanted(int i) {
    return i == 1 || i == 2 || i == 3 || i == 255 || i == 256 || i == 257;
}

int main(void) {
    if (sodium_init() < 0) {
        return 1;
    }
    unsigned char key[crypto_secretbox_KEYBYTES];
    memcpy(key, key_text, sizeof key);

    printf("# Generated by testdata/gen/golden.c with libsodium %s.\n",
           sodium_version_string());
    printf("# key %s; plaintext for operation i is \"packet i\".\n", key_text);
    printf("# columns: direction index nonce box\n");

    for (int dir = 0; dir <= 1; dir++) {
        unsigned char nonce[crypto_secretbox_NONCEBYTES] = {0};
        nonce[crypto_secretbox_NONCEBYTES - 1] = (unsigned char)dir;
        for (int i = 1; i <= 257; i++) {
            char msg[32];
            int n = snprintf(msg, sizeof msg, "packet %d", i);
            unsigned char box[crypto_secretbox_MACBYTES + sizeof msg];
            increment(nonce);
            crypto_secretbox_easy(box, (const unsigned char *)msg, (unsigned long long)n,
                                  nonce, key);
            if (wanted(i)) {
                printf("%d %d ", dir, i);
                hex(nonce, sizeof nonce);
                printf(" ");
                hex(box, crypto_secretbox_MACBYTES + (size_t)n);
                printf("\n");
            }
        }
    }
    return 0;
}
